  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant insideConstrainedOut ==> generated[|generated| - |currentConstrainedOut|..] == currentConstrainedOut
  invariant helpers.cost == steps
  invariant cost == 0
  decreases maxSteps - steps
{
  if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      steps := maxSteps;
    } else {
      generated := generated + [next];
      suffix := suffix + [next];
      if Contains(next, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else {
    var completeNow := parser.IsCompletePrefix(currentConstrainedOut);
    if completeNow {
      insideConstrainedOut := false;
      currentConstrainedOut := [];
    } else {
      var narrow := helpers.DeadEndDetection(parser, currentConstrainedOut, 2);
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next: Token;
      if narrow {
        next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
      } else {
        var softNext, isValid := helpers.SoftConstrainedStep(
          lm, parser, constrainedPrompt, currentConstrainedOut, 2.0, eosToken
        );
        next := softNext;
      }
      steps := steps + 1;
      if next == eosToken {
        steps := maxSteps;
      } else {
        generated := generated + [next];
        suffix := suffix + [next];
        if Contains(next, ">>") {
          insideConstrainedOut := false;
          currentConstrainedOut := [];
        } else {
          var updatedConstrained := currentConstrainedOut + [next];
          var updatedComplete := parser.IsCompletePrefix(updatedConstrained);
          if updatedComplete {
            insideConstrainedOut := false;
            currentConstrainedOut := [];
          } else {
            currentConstrainedOut := updatedConstrained;
          }
        }
      }
    }
  }
}

cost := helpers.cost;
